def build_agent(sandbox):
    # Create multiple columns spaced to avoid keep-out zone and distribute forces
    cols = []
    col_positions = [7.0, 8.0, 9.0, 11.0, 12.0, 13.0]
    for x in col_positions:
        col = sandbox.add_beam(x, 2.0, 0.4, 4.0, angle=0, density=5.0)
        cols.append(col)

    # Anchor each column to the ground
    for col in cols:
        sandbox.add_joint(col, None, (col.position.x, 0.0), type='rigid')

    # Add a wide roof beam to distribute impact forces across multiple joints
    roof = sandbox.add_beam(10.0, 4.2, 6.0, 0.4, angle=0, density=5.0)

    # Connect roof to all columns at their top ends (y=4.0)
    for col in cols:
        sandbox.add_joint(col, roof, (col.position.x, 4.0), type='rigid')

    return cols[0]  # Return any column as the chassis (no control logic needed)
